#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Celastrina's one-time release setup (docs/release-keystore.md), run by the maintainer, never by an agent:
# make the repository public (environment secrets and tag rules need that on GitHub Free), generate the signing
# key, back it up, record its fingerprint, and give the `release` environment its secrets.
#
#   scripts/release-setup.sh
#
# Nothing goes to .env. The key lives in $KEY_DIR only until stage 8 deletes it; the passwords stay in memory.

REPO="${CELASTRINA_REPO:-MasonNight/celastrina}"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
KEY_DIR="${CELASTRINA_KEY_DIR:-$HOME/.celastrina-release-key}"
KEYSTORE="$KEY_DIR/celastrina-release.jks"
ALIAS=celastrina
MARKER='<!-- release-certificate-sha256 -->'

# env_secret NAME VALUE sets a secret of the release environment (the library's set_secret sets repository ones).
env_secret() {
  if printf '%s' "$2" | gh secret set "$1" --env release --repo "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("release/$1")
    printf '  %s✓ set%s release secret %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("release secret $1: gh secret set $1 --env release --repo $REPO")
    warn "couldn't set $1"
  fi
}

# keystore_opens FILE: the file is a keystore that $KS_PASS opens, holding $ALIAS.
keystore_opens() { keytool -list -keystore "$1" -storepass:env KS_PASS -alias "$ALIAS" >/dev/null 2>&1; }

run_wizard() {

TOTAL_STAGES=8
ENV_FILE=/dev/null   # never persist anything from this wizard
export KS_PASS=""

banner "Celastrina release setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the tools this wizard needs."
missing=()
for tool in keytool gh base64 sha256sum awk; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
if (( ${#missing[@]} )); then warn "missing: ${missing[*]} (keytool comes with JDK 17)"; exit 1; fi
gh auth status >/dev/null 2>&1 || { warn "gh isn't logged in: run gh auth login, then re-run"; exit 1; }
perm="$(gh repo view "$REPO" --json viewerPermission --jq .viewerPermission)"
[[ "$perm" == ADMIN ]] || { warn "gh's account has $perm on $REPO; it needs ADMIN"; exit 1; }
recorded="$(sed -n "/^$MARKER\$/{n;p;}" "$ROOT/README.md")"
if [[ ! -f "$KEYSTORE" && "$recorded" != *PLACEHOLDER* ]]; then
  warn "README.md already records a release key ($recorded),"
  warn "and $KEYSTORE isn't here. This wizard makes the first key; it doesn't rotate one."
  exit 1
fi
step "keytool, gh (admin on $REPO), base64: all present."
note "The key will be generated in $KEY_DIR (only you can read it) and deleted in stage 8."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Make the repository public"
visibility="$(gh repo view "$REPO" --json visibility --jq .visibility)"
if [[ "$visibility" == PUBLIC ]]; then
  step "$REPO is already public."
  pause
else
  say "On GitHub Free, a private repository can't have environment secrets or tag-only rules,"
  say "so the signing key could only be a repository secret any branch's workflow can read."
  say "Going public makes these visible to everyone, for good (forks and clones can't be recalled):"
  step "all code and its full git history, including commit author emails"
  step "issues, pull requests and Actions logs"
  note "Agents scanned the history on 2026-11-26: no tokens or keys, only commit emails and"
  note "the TV's LAN address (192.168.1.29). Check anything you're unsure of before saying yes."
  open_url "https://github.com/$REPO"
  if confirm "Make $REPO public now?"; then
    gh repo edit "$REPO" --visibility public --accept-visibility-change-consequences
    step "$REPO is public."
  else
    warn "Stopping: the release environment needs a public repository (or GitHub Pro)."; exit 1
  fi
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Generate the signing key"
if [[ -f "$KEYSTORE" ]]; then
  say "A key from an earlier run is already in $KEYSTORE; reusing it."
  while :; do
    ask_secret KS_PASS "Its password:"
    keystore_opens "$KEYSTORE" && break
    warn "That password doesn't open it. Try again."
  done
else
  say "One key signs every Celastrina release, for its whole life. Lose it and no TV can update"
  say "without uninstalling first; leak it and anyone can publish an update every TV would install."
  step "Make a long random password in your password manager and save it there now."
  while :; do
    ask_secret KS_PASS "Paste the password:"
    ask_secret KS_PASS_AGAIN "Paste it again:"
    if [[ ${#KS_PASS} -lt 16 ]]; then warn "Use at least 16 characters."
    elif [[ "$KS_PASS" != "$KS_PASS_AGAIN" ]]; then warn "They differ. Try again."
    else break; fi
  done
  unset KS_PASS_AGAIN
  (umask 077 && mkdir -p "$KEY_DIR")
  # PKCS12 uses one password for the store and the key. 10958 days is 30 years.
  (umask 077 && keytool -genkeypair -keystore "$KEYSTORE" -storetype PKCS12 \
    -alias "$ALIAS" -keyalg RSA -keysize 4096 -validity 10958 \
    -dname "CN=Celastrina, O=Celastrina" -storepass:env KS_PASS -keypass:env KS_PASS >/dev/null 2>&1)
  keystore_opens "$KEYSTORE" || { warn "keytool didn't produce a usable keystore"; exit 1; }
  step "Generated $KEYSTORE (RSA 4096, 30 years, alias $ALIAS)."
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Two offline backups"
say "Copy the key to two offline media kept in different places (say, two encrypted USB drives,"
say "one at home and one elsewhere). Keep the password and alias ($ALIAS) in your password"
say "manager, apart from the drives."
step "Copy from: $KEYSTORE"
original="$(sha256sum < "$KEYSTORE")"
for n in 1 2; do
  while :; do
    ask "BACKUP_$n" "Path of backup $n (the copied .jks file):"
    path="BACKUP_$n"; path="${!path/#\~/$HOME}"
    if [[ ! -f "$path" ]]; then warn "No file at $path."
    elif [[ "$(sha256sum < "$path")" != "$original" ]]; then warn "$path isn't an exact copy. Copy it again."
    elif ! keystore_opens "$path"; then warn "$path doesn't open with your password."
    else step "Backup $n is an exact copy and opens."; break; fi
  done
done
[[ "$BACKUP_1" != "$BACKUP_2" ]] || warn "Both backups are the same path; make sure they're on different media."
pause "Unmount and put away both drives, then press Enter"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Record the fingerprint"
FINGERPRINT="$(keytool -list -v -keystore "$KEYSTORE" -storepass:env KS_PASS -alias "$ALIAS" \
  | awk '/SHA256:/ {print $2; exit}')"
[[ "$FINGERPRINT" =~ ^([0-9A-F]{2}:){31}[0-9A-F]{2}$ ]] || { warn "couldn't read the fingerprint"; exit 1; }
say "The certificate's SHA-256 fingerprint (public; it goes in the README):"
printf '\n    %s%s%s\n\n' "$BOLD" "$FINGERPRINT" "$RESET"
for doc in README.md INSTALL.md; do
  awk -v marker="$MARKER" -v line="\`$FINGERPRINT\`" \
    'after { print line; after = 0; next } { print } $0 == marker { after = 1 }' \
    "$ROOT/$doc" > "$ROOT/$doc.tmp" && mv "$ROOT/$doc.tmp" "$ROOT/$doc"
  step "Wrote it under the marker in $doc."
done
note "Commit those two files and merge them to main before the first tag (or ask an agent to"
note "open the PR). The release workflow refuses an APK whose certificate isn't the README's."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The release environment"
say "Creating the release environment on $REPO, usable only from v* tags."
gh api -X PUT "repos/$REPO/environments/release" --input - >/dev/null <<'JSON'
{"deployment_branch_policy": {"protected_branches": false, "custom_branch_policies": true}}
JSON
if gh api "repos/$REPO/environments/release/deployment-branch-policies" \
    --jq '.branch_policies[] | select(.type == "tag" and .name == "v*") | .id' | grep -q .; then
  step "The v* tag rule is already there."
else
  gh api -X POST "repos/$REPO/environments/release/deployment-branch-policies" -f name='v*' -f type=tag >/dev/null
  step "Only v* tags can deploy to release."
fi
if gh api "repos/$REPO/rulesets" --jq '.[] | select(.name == "Release tags") | .id' | grep -q .; then
  step "The Release tags ruleset is already there."
else
  gh api -X POST "repos/$REPO/rulesets" --input - >/dev/null <<'JSON'
{"name": "Release tags", "target": "tag", "enforcement": "active",
 "conditions": {"ref_name": {"include": ["refs/tags/v*"], "exclude": []}},
 "rules": [{"type": "creation"}, {"type": "update"}, {"type": "deletion"}],
 "bypass_actors": [{"actor_id": 5, "actor_type": "RepositoryRole", "bypass_mode": "always"}]}
JSON
  step "Only repository admins (you) can create, move or delete v* tags."
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The release secrets"
props="$HOME/.gradle/gradle.properties"
TMDB_API_KEY=""
if [[ -f "$props" ]] && grep -q '^TMDB_API_KEY=' "$props" && confirm "Use the TMDB_API_KEY in $props?"; then
  TMDB_API_KEY="$(sed -n 's/^TMDB_API_KEY=//p' "$props" | tail -n1 | tr -d '\r')"
fi
if [[ -z "$TMDB_API_KEY" ]]; then
  open_url "https://www.themoviedb.org/settings/api"
  step "Copy the project's API Key (v3 auth)."
  ask_secret TMDB_API_KEY "Paste the TMDB key:"
fi
env_secret RELEASE_KEYSTORE_BASE64 "$(base64 < "$KEYSTORE" | tr -d '\n')"
env_secret RELEASE_KEYSTORE_PASSWORD "$KS_PASS"
env_secret RELEASE_KEY_PASSWORD "$KS_PASS"
env_secret RELEASE_KEY_ALIAS "$ALIAS"
env_secret TMDB_API_KEY "$TMDB_API_KEY"
unset TMDB_API_KEY
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Delete the key from this machine"
say "The two backups and the release environment now hold the key. This machine is shared with"
say "agents, so it shouldn't keep a copy."
if (( ${#SKIPPED[@]} )); then
  warn "Some secrets weren't set, so the key stays in $KEY_DIR until you re-run this wizard."
elif confirm "Delete $KEY_DIR?"; then
  shred -u "$KEYSTORE" 2>/dev/null || rm -f "$KEYSTORE"
  rmdir "$KEY_DIR" 2>/dev/null || true
  step "Deleted."
else
  SKIPPED+=("delete $KEY_DIR (the signing key) from this machine")
fi
unset KS_PASS

finish
say "Next: merge the README/INSTALL fingerprint to main, then release:"
say "  git fetch origin && git tag v0.1.0 origin/main && git push origin v0.1.0"
printf '\n'
}

run_wizard "$@"; exit
